module web.title_length
  purpose: Measure the title of a web page for agents.

import std.http as web
import std.http exposing Url

public type TitleError is one of
  purpose: Why a page title could not be measured.
  BadUrl(address: Text)
  DownloadFailed(address: Text)
  NoTitle(address: Text)
end

public function title_characters(page: Text, address: Text)
  returns Integer
  or fails with TitleError
  purpose: Count the characters in the title element of an HTML text, failing with NoTitle when there is none.
  tags: html, text
  example: title_characters("<html><title>Hello</title></html>", address: "x") is 5

  let lowered be page.to_lower()
  let open be lowered.index_of("<title>") otherwise fail with NoTitle(address: address)
  let after be page.drop(open + 7)
  let lowered_after be after.to_lower()
  let close be lowered_after.index_of("</title>") otherwise fail with NoTitle(address: address)
  return after.take(close).trim().length()
end

public function page_title_length(address: Text)
  returns Integer
  or fails with TitleError
  needs network.http
  purpose: Download the page at the address and return the number of characters in its title element, failing with a clear error when it has no title.
  tags: web, html, agent
  expose as tool

  let url be Url(address) otherwise fail with BadUrl(address: address)
  let page be web.get(url) otherwise fail with DownloadFailed(address: address)
  return title_characters(page, address: address)
end
